def parse_version(s):
    if not s:
        raise ValueError('empty string')
    parts = s.split('.')
    result = []
    for part in parts:
        if part == '':
            raise ValueError('empty component')
        if not part.isdigit() or (len(part) > 1 and part[0] == '0'):
            raise ValueError('non-numeric component or leading zero')
        result.append(int(part))
    return result
